import unittest

from app.billing import apply_discount


class TestApplyDiscountMissingRateStillGuarded(unittest.TestCase):
    """A promotion with no rate must be a no-op, not an exception."""

    def test_missing_rate_is_a_no_op(self):
        self.assertEqual(apply_discount(100.0, None), 100.0)


if __name__ == "__main__":
    unittest.main()
